    17	#include <QImage>
    18	#include <QIODevice>
    19	#include <QFile>
    20	
    21	static constexpr char s_magic[] = "application/x-krita";
    22	static constexpr int s_magic_size = sizeof(s_magic) - 1; // -1 to remove the last \0
    23	
    24	KraHandler::KraHandler()
    25	{
    26	}
    27	
    28	bool KraHandler::canRead() const
    29	{
    30	    if (canRead(device())) {
    31	        setFormat("kra");
    32	        return true;
    33	    }
    34	    return false;
    35	}
    36	
    37	bool KraHandler::read(QImage *image)
    38	{
    39	    KZip zip(device());
    40	    if (!zip.open(QIODevice::ReadOnly)) return false;
    41	
    42	    const KArchiveEntry *entry = zip.directory()->entry(QLatin1String("mergedimage.png"));
    43	    if (!entry || !entry->isFile()) return false;
    44	
    45	    const KZipFileEntry* fileZipEntry = static_cast<const KZipFileEntry*>(entry);
    46	
    47	    image->loadFromData(fileZipEntry->data(), "PNG");
    48	
    49	    return true;
    50	}
    51	
    52	bool KraHandler::canRead(QIODevice *device)
    53	{
    54	    if (!device) {
    55	        qWarning("KraHandler::canRead() called with no device");
    56	        return false;
    57	    }
    58	
    59	    char buff[57];
    60	    if (device->peek(buff, sizeof(buff)) == sizeof(buff))
    61	        return memcmp(buff + 0x26, s_magic, s_magic_size) == 0;
    62	
    63	    return false;
    64	}
    65	
    66	QImageIOPlugin::Capabilities KraPlugin::capabilities(QIODevice *device, const QByteArray &format) const
    67	{
    68	    if (format == "kra" || format == "KRA") {
    69	        return Capabilities(CanRead);
    70	    }
    71	    if (!format.isEmpty()) {
    72	        return {};
    73	    }
    74	    if (!device->isOpen()) {
    75	        return {};
    76	    }
    77	
    78	    Capabilities cap;
    79	    if (device->isReadable() && KraHandler::canRead(device)) {
    80	        cap |= CanRead;
    81	    }
    82	    return cap;
    83	}
    84	
    85	QImageIOHandler *KraPlugin::create(QIODevice *device, const QByteArray &format) const
    86	{
    87	    QImageIOHandler *handler = new KraHandler;
    88	    handler->setDevice(device);
    89	    handler->setFormat(format);
    90	    return handler;
    91	}
